effect.shader:
// Port of veggy-fx's clean-room TV Simulator (recovered from Sony's
// vfx1.dll). Work is done in the original's units: pixel
// coordinates with the origin at the top-left and 0..255 values.

// Uniform pseudo-random value in [-1, 1).
float hash(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z) * 2.0 - 1.0;
}

// The original fills a 64x32 lattice from the MSVC rand() sequence.
// GLSL ES 1.00 can't run that 32-bit generator, so each cell uses a
// hash with the same uniform [-1, 1) distribution instead.
float lattice(float x, float y) {
    return hash(vec2(mod(x, 32.0), mod(y, 64.0)) + vec2(17.0, 59.0));
}

float cubic(float p0, float p1, float p2, float p3, float x) {
    return p1 + 0.5 * x * (p2 - p0 + x * (2.0 * p0 - 5.0 * p1 + 4.0 * p2 - p3
           + x * (3.0 * (p1 - p2) + p3 - p0)));
}

float latticeRow(float ix, float iy, float fx) {
    return cubic(lattice(ix, iy), lattice(ix + 1.0, iy),
                 lattice(ix + 2.0, iy), lattice(ix + 3.0, iy), fx);
}

float latticeNoise(float x, float y) {
    float ix = floor(x) - 1.0;
    float iy = floor(y) - 1.0;
    float fx = x - floor(x);
    float fy = y - floor(y);
    return cubic(latticeRow(ix, iy, fx), latticeRow(ix, iy + 1.0, fx),
                 latticeRow(ix, iy + 2.0, fx), latticeRow(ix, iy + 3.0, fx), fy);
}

// Horizontal displacement in pixels for one source scanline.
float lineSyncOffset(float row, float h, float w, float t, float zoom, float strength) {
    if (strength <= 0.0) return 0.0;
    float sum = 0.0;
    float amp = strength;
    float space = 4.567 / zoom;
    float timeScale = 6.213;
    for (int i = 0; i < 6; i++) {
        float x = mod(2.0 * (row + 1.0) * space / h, 32.0);
        float y = mod(2.0 * t * timeScale, 64.0);
        sum += amp * 0.15 * w * latticeNoise(x, y);
        amp /= 2.71;
        space *= 2.231;
        timeScale *= 2.142;
    }
    return sum;
}

float smoothNoise(float x, float seed) {
    float i = floor(x);
    float f = x - i;
    float u = f * f * (3.0 - 2.0 * f);
    return hash(vec2(i, seed)) * (1.0 - u) + hash(vec2(i + 1.0, seed)) * u;
}

// Interlace table .8 1.2 1.2 1.2 1.2 .8 .5 .2 .2 .5, linearly
// interpolated and wrapping.
float interlaceEntry(float i) {
    if (i < 0.5) return 0.8;
    if (i < 4.5) return 1.2;
    if (i < 5.5) return 0.8;
    if (i < 6.5) return 0.5;
    if (i < 8.5) return 0.2;
    return 0.5;
}

float interlaceAt(float p) {
    p = mod(p, 10.0);
    float i = floor(p);
    return mix(interlaceEntry(i), interlaceEntry(mod(i + 1.0, 10.0)), p - i);
}

// Scan band table 1 1.7 2.5 1.7 1.
float scanEntry(float i) {
    if (i < 0.5) return 1.0;
    if (i < 1.5) return 1.7;
    if (i < 2.5) return 2.5;
    if (i < 3.5) return 1.7;
    return 1.0;
}

float scanAt(float p) {
    p = mod(p, 5.0);
    float i = floor(p);
    return mix(scanEntry(i), scanEntry(mod(i + 1.0, 5.0)), p - i);
}

// Five-position aperture grille: black, red, green, blue, black.
vec3 grilleEntry(float i) {
    if (i < 0.5) return vec3(0.0);
    if (i < 1.5) return vec3(192.0, 0.0, 0.0);
    if (i < 2.5) return vec3(0.0, 192.0, 0.0);
    if (i < 3.5) return vec3(0.0, 0.0, 192.0);
    return vec3(0.0);
}

vec3 grilleAt(float phase) {
    phase = mod(phase, 4.0);
    float i = floor(phase);
    return mix(grilleEntry(i), grilleEntry(i + 1.0), phase - i);
}

void main() {
    float zoom = detailZoom;
    float grill = apertureGrill;
    float inter = interlacing;
    float lineS = lineSync;
    float vertS = verticalSync;
    float scanP = scanPhasing;
    float phos = phosphorescence;
    float stat = statik;

    // Original preset vectors, in dialog order.
    if (preset == 1) {
        zoom = 1.0; grill = 0.316; inter = 0.66; lineS = 1.0;
        vertS = 1.0; scanP = 0.15; phos = 0.9; stat = 0.0;
    } else if (preset == 2) {
        zoom = 1.0; grill = 0.316; inter = 0.78; lineS = 0.32;
        vertS = 0.254; scanP = 0.2; phos = 0.5; stat = 0.0;
    } else if (preset == 3) {
        zoom = 1.0; grill = 0.0; inter = 0.0; lineS = 1.0;
        vertS = 1.0; scanP = 0.0; phos = 0.0; stat = 0.0;
    }
    zoom = max(zoom, 1.0);

    float w = acScreenSize.x;
    float h = acScreenSize.y;
    float t = acTime;

    // Pixel coordinates as the original sees them.
    float x = acScreenNorm.x * w - 0.5;
    float y = (1.0 - acScreenNorm.y) * h - 0.5;
    float cx = (w - 1.0) * 0.5;
    float cy = (h - 1.0) * 0.5;

    float grilleStep = 10.0 / (2.0 * h * 0.011127083333333334) / zoom;
    float aperture = 0.75 * max(grill, stat);

    float phosJitter = hash(vec2(floor(t * 1000.0), 7.0)) * 0.05 * phos;
    vec3 phosGamma = clamp(vec3(1.0 - 0.6 * phos, 1.0 - 0.5 * phos, 1.0 - 0.15 * phos)
                           + phosJitter, 0.05, 2.0);

    float verticalRoll = (1.0 - vertS) * h * fract(t * 0.3333333 + 0.137);

    float sy = mod((y - cy) / zoom + cy + verticalRoll, h);
    float jitter = lineSyncOffset(floor(sy), h, w, t, zoom, 1.0 - lineS);

    float scan = (1.0 - inter) + inter * interlaceAt(sy);
    if (scanP > 0.0001) {
        float scanHeight = h * 0.35 * zoom;
        float center = fract(t * 3.0 * scanP) * h * zoom + (h - h * zoom) * 0.5;
        float scanStart = center - scanHeight * 0.5;
        if (y > scanStart && y <= scanStart + scanHeight) {
            scan *= scanAt(4.0 * (y - scanStart) / scanHeight);
        }
    }

    float sx = (x - cx) / zoom + cx + jitter;
    vec2 uv = vec2((clamp(sx, 0.0, w - 1.0) + 0.5) / w,
                   1.0 - (clamp(sy, 0.0, h - 1.0) + 0.5) / h);

    vec4 src = texture2D(inputImg.texture, uv);
    float a = src.a;
    vec3 v = src.rgb / max(a, 0.0001) * 255.0;

    float phase = x * grilleStep;
    vec3 g = grilleAt(phase);
    if (stat > 0.0) {
        float nx = phase * 0.5 + t * 23.0;
        g += 127.5 * stat * vec3(smoothNoise(nx, y * 3.0),
                                 smoothNoise(nx, y * 3.0 + 1.0),
                                 smoothNoise(nx, y * 3.0 + 2.0));
    }

    v = (v * (1.0 - aperture) + aperture * (2.0 * v * g / 256.0 + g * 0.25)) * scan;
    v = pow(clamp(v / 255.0, 0.0, 1.0), phosGamma);

    gl_FragColor = vec4(v * a, a);
}
